    # ═══════════════════════════════════════════════════════════════════════════
    # Test 1: Node_Ids Flow Through Pipeline (Phase A → B → C)
    # ═══════════════════════════════════════════════════════════════════════════

    def test_1__node_ids_present_in_html_dict(self):             # Verify html_dict has node_ids (Phase A output).
        html_dict = get_html_dict('simple')

        dict_node_ids = collect_node_ids_from_dict(html_dict)

        assert len(dict_node_ids) > 0, "Dict should have node_ids"
        assert dict_node_ids == {'f0000001',
                                 'f0000002',
                                 'f0000003',
                                 'f0000004',
                                 'f0000005',
                                 'f0000006',
                                 'f0000007'}
        assert dict_node_ids != {'PLACEHOLDER_b_001',
                                 'PLACEHOLDER_body_001',
                                 'PLACEHOLDER_div_001',
                                 'PLACEHOLDER_html_001',
                                 'PLACEHOLDER_text_001',
                                 'PLACEHOLDER_text_002',
                                 'PLACEHOLDER_text_003'}

    def test_1b__node_ids_present_in_mgraph(self):  # Verify MGraph has node_ids (Phase B output).
        body_graph_json = get_body_graph_json('simple')

        assert type(body_graph_json) is dict
        assert body_graph_json       != {}

        mgraph          = load_mgraph_from_json(body_graph_json)

        assert type(mgraph) is MGraph
        assert mgraph.export().to__mgraph_json() != {'edges': {},
                                                     'graph_data': None,
                                                     'graph_id': mgraph.graph.graph_id(),
                                                     'graph_path': None,
                                                     'graph_type': None,
                                                     'index_config': None,
                                                     'nodes': {},
                                                     'schema_types': None}
        mgraph_node_ids = collect_node_ids_from_mgraph(mgraph)



        assert len(mgraph_node_ids) > 0, "MGraph should have node_ids"
        assert mgraph.graph.model.data.nodes.obj() == __(c0000003=__(node_data=None,
                                                                     node_path=None,
                                                                     node_type='mgraph_db.mgraph.schemas.Schema__MGraph__Node.Schema__MGraph__Node',
                                                                     node_id='c0000003'),
                                                         f0000002=__(node_data=None,
                                                                     node_path='body',
                                                                     node_type='mgraph_db.mgraph.schemas.Schema__MGraph__Node.Schema__MGraph__Node',
                                                                      node_id='f0000002'),
                                                       f0000003=__(node_data=None,
                                                                   node_path='body.div',
                                                                   node_type='mgraph_db.mgraph.schemas.Schema__MGraph__Node.Schema__MGraph__Node',
                                                                   node_id='f0000003'),
                                                       f0000004=__(node_data=__(value_type='builtins.str',
                                                                                value='Hello ',
                                                                                key='f0000003:0'),
                                                                   node_id='f0000004',
                                                                   node_type='mgraph_db.mgraph.schemas.Schema__MGraph__Node__Value.Schema__MGraph__Node__Value',
                                                                   node_path='text'),
                                                       f0000005=__(node_data=None,
                                                                   node_path='body.div.b',
                                                                   node_type='mgraph_db.mgraph.schemas.Schema__MGraph__Node.Schema__MGraph__Node',
                                                                   node_id='f0000005'),
                                                       f0000006=__(node_data=__(value_type='builtins.str',
                                                                                value='World',
                                                                                key='f0000005:0'),
                                                                   node_id='f0000006',
                                                                   node_type='mgraph_db.mgraph.schemas.Schema__MGraph__Node__Value.Schema__MGraph__Node__Value',
                                                                   node_path='text'),
                                                       f0000007=__(node_data=__(value_type='builtins.str',
                                                                                value='!',
                                                                                key='f0000003:2'),
                                                                   node_id='f0000007',
                                                                   node_type='mgraph_db.mgraph.schemas.Schema__MGraph__Node__Value.Schema__MGraph__Node__Value',
                                                                   node_path='text'))

    def test_1c__node_ids_match_between_dict_and_mgraph(self):
        """Verify node_ids from dict appear in MGraph (Phase A → B connection)."""
        fixture = get_fixture('simple')
        html_dict, mgraph = load_fixture_for_transform(fixture)

        dict_node_ids   = collect_node_ids_from_dict(html_dict)
        mgraph_node_ids = collect_node_ids_from_mgraph(mgraph)

        # Body-related node_ids should overlap
        # (html_dict includes head, mgraph is just body)
        body_dict = html_dict['nodes'][0] if html_dict.get('nodes') else html_dict
        for node in html_dict.get('nodes', []):
            if isinstance(node, dict) and node.get('tag') == 'body':
                body_dict = node
                break

        body_dict_ids = collect_node_ids_from_dict(body_dict)
        common_ids = body_dict_ids & mgraph_node_ids

        assert len(common_ids) > 0, "MGraph should reuse node_ids from dict"

    def test_1d__node_ids_in_tracking_data_match_original(self):
        """Node_ids in tracking data should match original dict."""
        fixture = get_fixture('multiple_wrappers')
        html_dict, mgraph = load_fixture_for_transform(fixture)

        transformer = Html_Use_Case__3__Source_Tracking()
        transformer.transform_mgraph(mgraph)

        wrapper_mapping = transformer.get_all_wrapper_mappings()
        dict_node_ids = collect_node_ids_from_dict(html_dict)

        for wrapper_id in wrapper_mapping.keys():
            assert wrapper_id in dict_node_ids, f"Wrapper {wrapper_id} should be from original dict"

