    def test_4__can_find_wrapper_in_dict(self):
        """Should be able to locate wrapper element in original dict."""
        fixture = get_fixture('simple')
        html_dict, mgraph = load_fixture_for_transform(fixture)

        transformer = Html_Use_Case__3__Source_Tracking()
        transformer.transform_mgraph(mgraph)

        wrapper_mapping = transformer.get_all_wrapper_mappings()

        for wrapper_id, info in wrapper_mapping.items():
            node, parent, index = find_node_by_id(html_dict, wrapper_id)

            assert node   is not None, f"Should find wrapper {wrapper_id}"
            assert parent is not None, f"Wrapper should have parent"
            assert index  is not None, f"Wrapper should have index in parent"

            tag = node.get('tag', '').lower()
            assert tag in {'a', 'b', 'i', 'span', 'strong', 'em'}, f"Expected inline tag, got {tag}"

    def test_4b__can_find_text_sources_in_dict(self):
        """Should be able to locate source text nodes in original dict."""
        fixture = get_fixture('simple')
        html_dict, mgraph = load_fixture_for_transform(fixture)

        transformer = Html_Use_Case__3__Source_Tracking()
        transformer.transform_mgraph(mgraph)

        source_mapping = transformer.get_all_source_mappings()

        for merged_id, source_ids in source_mapping.items():
            for source_id in source_ids:
                node, parent, index = find_node_by_id(html_dict, source_id)

                assert node is not None, f"Should find source {source_id}"
                assert node.get('type') == 'TEXT', f"Source should be TEXT node"

    # ═══════════════════════════════════════════════════════════════════════════
    # Test 5: Unwrap Elements to Produce Clean HTML (Phase E Preview)
    # ═══════════════════════════════════════════════════════════════════════════

    def test_5__unwrap_single_element(self):
        """Unwrapping single element should preserve children."""
        fixture = get_fixture('simple')
        html_dict, mgraph = load_fixture_for_transform(fixture)

        transformer = Html_Use_Case__3__Source_Tracking()
        transformer.transform_mgraph(mgraph)

        wrapper_mapping = transformer.get_all_wrapper_mappings()

        # Unwrap all wrappers
        for wrapper_id in wrapper_mapping.keys():
            result = unwrap_element_in_dict(html_dict, wrapper_id)
            assert result is True, f"Should unwrap {wrapper_id}"

        # Convert back to HTML
        output_html = html_dict_to_html(html_dict)

        # Should not contain <b> tag anymore
        assert '<b>' not in output_html, f"Should not have <b> tag: {output_html}"
        assert 'World' in output_html, f"Should preserve text content: {output_html}"

    def test_5b__unwrap_multiple_elements(self):
        """Unwrapping multiple elements should produce clean HTML."""
        fixture = get_fixture('multiple_wrappers')
        html_dict, mgraph = load_fixture_for_transform(fixture)

        transformer = Html_Use_Case__3__Source_Tracking()
        transformer.transform_mgraph(mgraph)

        wrapper_mapping = transformer.get_all_wrapper_mappings()

        # Unwrap all wrappers
        for wrapper_id in wrapper_mapping.keys():
            unwrap_element_in_dict(html_dict, wrapper_id)

        # Merge adjacent text nodes
        merge_adjacent_text_nodes(html_dict)

        # Convert back to HTML
        output_html = html_dict_to_html(html_dict)

        # Should not contain inline tags
        assert '<a>' not in output_html.lower(), f"Should not have <a>: {output_html}"
        assert '<b>' not in output_html.lower(), f"Should not have <b>: {output_html}"

        # Should preserve all text
        assert 'Start'  in output_html
        assert 'link'   in output_html
        assert 'middle' in output_html
        assert 'bold'   in output_html
        assert 'end'    in output_html

    def test_5c__full_workflow_nested_structure(self):
        """Full workflow with nested HTML structure."""
        fixture           = get_fixture('nested_structure')
        input_html        = fixture.get('html')

        html_dict, mgraph = load_fixture_for_transform(fixture)

        # Phase C: Transform with tracking
        transformer = Html_Use_Case__3__Source_Tracking()
        transformer.transform_mgraph(mgraph)

        # Get tracking data
        wrapper_mapping = transformer.get_all_wrapper_mappings()
        source_mapping  = transformer.get_all_source_mappings()

        # Verify we captured wrappers (a, b, i)
        assert len(wrapper_mapping) >= 3, f"Should have 3+ wrappers, got {len(wrapper_mapping)}"

        # Unwrap all inline elements
        for wrapper_id in wrapper_mapping.keys():
            unwrap_element_in_dict(html_dict, wrapper_id)

        # Merge adjacent text nodes
        merge_adjacent_text_nodes(html_dict)

        # Convert back to HTML
        output_html = html_dict_to_html(html_dict)

        # Verify clean output
        assert '<a'  not in output_html.lower()
        assert '<i'  not in output_html.lower()

        # Verify text preserved
        assert 'link' in output_html
        assert 'bold' in output_html

        assert input_html  == ('<!DOCTYPE html>\n'
                               '<html>\n'
                               '    <body>\n'
                               '        <div>\n'
                               '            This is a <a href="">link</a> with some <b>bold</b> in the mix\n'
                               '        </div>\n'
                               '        <div>\n'
                               '            this is the <i>2nd div</i> in here\n'
                               '        </div>\n'
                               '    </body>\n'
                               '</html>\n')
        assert output_html == ('<html><body><div>\n'
                               '            This is a link with some bold in the mix\n'
                               '        </div><div>\n'
                               '            this is the 2nd div in here\n'
                               '        </div></body></html>')